-- QA only, transactional: never retains fixtures or audit test entries.
BEGIN;
DO $$
DECLARE
 org uuid:='3868f88a-fa36-4467-9b31-653143c6ef7d';
 admin_id uuid:='119aa014-e89a-4075-9398-efb7db5d2a18';
 op uuid:='47b6c2b6-c423-43ca-9a04-c5995ee194df';
 rs uuid:='5f1c62c9-2971-4f2f-8068-fac70b332b20';
 ins uuid; reg uuid; semana uuid; at_id uuid; ex uuid; su uuid; at_su uuid; titular text;
 lecturas jsonb; datos jsonb; den boolean; snapshot jsonb; antes jsonb;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.organizations WHERE id=org AND es_prueba) THEN RAISE EXCEPTION 'Solo QA'; END IF;
 EXECUTE 'SET LOCAL ROLE authenticated';
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',admin_id,'role','authenticated')::text,true);
 INSERT INTO public.tend_instrumentos(org_id,codigo,tipo,parametro,spec_estado) VALUES(org,'T3B-QA','otro','Presión QA','validada') RETURNING id INTO ins;
 INSERT INTO public.tend_registros(org_id,modulo,nombre,instrumento_id) VALUES(org,'presiones','T3b QA',ins) RETURNING id INTO reg;
 SELECT jsonb_agg(jsonb_build_object('dia',dia,'turno',turno,'valor',10,'hora',NULL,'quien',NULL)) INTO lecturas
 FROM unnest(ARRAY['Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo']) dia CROSS JOIN unnest(ARRAY['Mañana','Media tarde','Tarde']) turno;
 datos:=jsonb_build_object('semana_inicio','2026-10-12','mes','CLIENTE','anio','9999','unidad','Pa','lecturas',lecturas,'source','ia','foto_path',org::text||'/qa.png');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',op,'role','authenticated')::text,true);
 semana:=public.tend_guardar_semana(reg,datos);
 IF NOT EXISTS(SELECT 1 FROM public.tend_semanas WHERE id=semana AND mes='octubre' AND anio='2026' AND source='manual') THEN RAISE EXCEPTION 'P fuente/mes servidor'; END IF;
 SELECT to_jsonb(s) INTO antes FROM public.tend_semanas s WHERE id=semana;
 den:=false;
 BEGIN PERFORM public.tend_guardar_semana(reg,datos||jsonb_build_object('observaciones','Cambio sin motivo'));
 EXCEPTION WHEN raise_exception THEN IF SQLERRM='Semana con lecturas previas requiere motivo' THEN den:=true; ELSE RAISE; END IF; END;
 IF NOT den THEN RAISE EXCEPTION 'Edición manual sin motivo permitida'; END IF;
 PERFORM public.tend_guardar_semana(reg,datos||jsonb_build_object('observaciones','Corrección QA'),'Motivo QA concreto');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',admin_id,'role','authenticated')::text,true);
 IF NOT EXISTS(SELECT 1 FROM public.audit_trail WHERE registro_id=semana::text AND accion='SEMANA_CORREGIDA' AND valor_anterior=antes AND valor_nuevo->>'motivo'='Motivo QA concreto' AND valor_nuevo->'semana'->>'observaciones'='Corrección QA') THEN RAISE EXCEPTION 'Falta auditoría de corrección'; END IF;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',op,'role','authenticated')::text,true);
 INSERT INTO public.tend_extracciones(org_id,registro_id,foto_path,modulo,solicitado_por) VALUES(org,reg,org::text||'/qa.png','presiones',op) RETURNING id INTO ex;
 EXECUTE 'RESET ROLE'; EXECUTE 'SET LOCAL ROLE service_role';
 PERFORM set_config('request.jwt.claims','{"role":"service_role"}',true);
 PERFORM public.tend_extraccion_resultado(ex,jsonb_build_object('lecturas',lecturas),'[{"clave":"qa","version":"1.0","sha256":"qa"}]','modelo-qa');
 EXECUTE 'RESET ROLE'; EXECUTE 'SET LOCAL ROLE authenticated';
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',op,'role','authenticated')::text,true);
 den:=false;
 BEGIN PERFORM public.tend_confirmar_extraccion(ex,datos);
 EXCEPTION WHEN raise_exception THEN IF SQLERRM='Semana con lecturas previas requiere motivo' THEN den:=true; ELSE RAISE; END IF; END;
 IF NOT den OR NOT EXISTS(SELECT 1 FROM public.tend_extracciones WHERE id=ex AND estado='propuesta') THEN RAISE EXCEPTION 'Extracción sin motivo no falló'; END IF;
 SELECT to_jsonb(s) INTO antes FROM public.tend_semanas s WHERE id=semana;
 PERFORM public.tend_confirmar_extraccion(ex,datos||jsonb_build_object('observaciones','Confirmación QA'),'Corrección IA QA');
 IF NOT EXISTS(SELECT 1 FROM public.tend_semanas WHERE id=semana AND source='ia') OR NOT EXISTS(SELECT 1 FROM public.tend_extracciones WHERE id=ex AND estado='confirmada') THEN RAISE EXCEPTION 'Confirmación IA no conserva origen'; END IF;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',admin_id,'role','authenticated')::text,true);
 IF NOT EXISTS(SELECT 1 FROM public.audit_trail WHERE registro_id=semana::text AND accion='SEMANA_CORREGIDA' AND valor_anterior=antes AND valor_nuevo->>'motivo'='Corrección IA QA' AND valor_nuevo->'semana'->>'source'='ia') THEN RAISE EXCEPTION 'Falta auditoría de confirmación IA'; END IF;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',op,'role','authenticated')::text,true);
 INSERT INTO public.tend_extracciones(org_id,registro_id,foto_path,modulo,solicitado_por) VALUES(org,reg,org::text||'/qa.png','presiones',op) RETURNING id INTO ex;
 EXECUTE 'RESET ROLE'; EXECUTE 'SET LOCAL ROLE service_role';
 PERFORM set_config('request.jwt.claims','{"role":"service_role"}',true);
 PERFORM public.tend_extraccion_resultado(ex,jsonb_build_object('lecturas',lecturas),'[{"clave":"qa","version":"1.0"}]','modelo-qa');
 EXECUTE 'RESET ROLE'; EXECUTE 'SET LOCAL ROLE authenticated';
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',op,'role','authenticated')::text,true);
 INSERT INTO public.tend_registros_at(org_id,sistema,periodo_desde,periodo_hasta,instrumentos) VALUES(org,'T3b QA','2026-10-12','2026-10-18',jsonb_build_array(jsonb_build_object('id',ins))) RETURNING id INTO at_id;
 den:=false;
 BEGIN UPDATE public.tend_registros_at SET formato_snapshot='{}' WHERE id=at_id;
 EXCEPTION WHEN raise_exception THEN IF SQLERRM='Snapshots reservados al servidor' THEN den:=true; ELSE RAISE; END IF; END;
 IF NOT den THEN RAISE EXCEPTION 'Snapshot cliente permitido'; END IF;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',rs,'role','authenticated')::text,true);
 UPDATE public.tend_registros_at SET estado='emitido' WHERE id=at_id;
 SELECT datos_snapshot INTO snapshot FROM public.tend_registros_at WHERE id=at_id;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(snapshot->'registros') r CROSS JOIN LATERAL jsonb_array_elements(r->'semanas') s WHERE s->>'id'=semana::text) THEN RAISE EXCEPTION 'Snapshot sin registro/semanas/id'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.tend_registros_at WHERE id=at_id AND formato_snapshot IS NOT NULL AND emitido_nombre IS NOT NULL) THEN RAISE EXCEPTION 'Emisión sin snapshot'; END IF;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',op,'role','authenticated')::text,true);
 den:=false;
 BEGIN PERFORM public.tend_guardar_semana(reg,datos||jsonb_build_object('observaciones','Manual prohibida'),'Motivo QA');
 EXCEPTION WHEN raise_exception THEN IF SQLERRM='Semana incluida en AT emitido: cambio rechazado' THEN den:=true; ELSE RAISE; END IF; END;
 IF NOT den THEN RAISE EXCEPTION 'Edición manual de emitido permitida'; END IF;
 den:=false;
 BEGIN PERFORM public.tend_confirmar_extraccion(ex,datos,'Motivo QA');
 EXCEPTION WHEN raise_exception THEN IF SQLERRM='Semana incluida en AT emitido: cambio rechazado' THEN den:=true; ELSE RAISE; END IF; END;
 IF NOT den THEN RAISE EXCEPTION 'Extracción de emitido permitida'; END IF;
 den:=false;
 BEGIN PERFORM public.tend_guardar_semana(reg,datos||jsonb_build_object('foto_path',org::text||'/../otra.png'),'Motivo QA');
 EXCEPTION WHEN raise_exception THEN IF SQLERRM='Foto fuera de empresa' THEN den:=true; ELSE RAISE; END IF; END;
 IF NOT den THEN RAISE EXCEPTION 'Foto con .. permitida'; END IF;
 den:=false;
 BEGIN PERFORM public.tend_guardar_semana(reg,datos||jsonb_build_object('foto_path','508ebdb4-12c1-4a9a-9767-cae539afef15/otra.png'),'Motivo QA');
 EXCEPTION WHEN raise_exception THEN IF SQLERRM='Foto fuera de empresa' THEN den:=true; ELSE RAISE; END IF; END;
 IF NOT den THEN RAISE EXCEPTION 'Foto de otra empresa permitida'; END IF;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',admin_id,'role','authenticated')::text,true);
 INSERT INTO public.org_suplencias(org_id,suplente_user_id,facultades,fecha_inicio,fecha_fin,motivo) VALUES(org,op,ARRAY['autorizar'],now()+interval '10 years',now()+interval '10 years 1 day','QA futuro rollback') RETURNING id INTO su;
 IF NOT EXISTS(SELECT 1 FROM public.org_suplencias WHERE id=su AND rs_titular_user_id=rs AND rs_titular_nombre IS NOT NULL) THEN RAISE EXCEPTION 'Titular no congelado'; END IF;
 INSERT INTO public.org_suplencias(org_id,suplente_user_id,facultades,fecha_inicio,fecha_fin,motivo) VALUES(org,op,ARRAY['autorizar'],now(),now()+interval '1 day','Suplencia emisión QA') RETURNING id INTO su;
 SELECT rs_titular_nombre INTO titular FROM public.org_suplencias WHERE id=su;
 INSERT INTO public.tend_registros_at(org_id,sistema,periodo_desde,periodo_hasta,instrumentos) VALUES(org,'Suplencia QA','2026-10-12','2026-10-18',jsonb_build_array(jsonb_build_object('id',ins))) RETURNING id INTO at_su;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',op,'role','authenticated')::text,true);
 UPDATE public.tend_registros_at SET estado='emitido' WHERE id=at_su;
 IF NOT EXISTS(SELECT 1 FROM public.tend_registros_at WHERE id=at_su AND en_suplencia AND suplencia_id=su AND rs_sustituido_nombre=titular) THEN RAISE EXCEPTION 'RS sustituido no procede de suplencia'; END IF;
 EXECUTE 'RESET ROLE';
END $$;
SELECT unnest(ARRAY['Extracción sobre lecturas sin motivo: PASA','Snapshot cliente rechazado: PASA','Emitido: edición manual rechazada: PASA','Emitido: extracción rechazada: PASA','Manual sin motivo rechazada: PASA','Manual con motivo auditada: PASA','Source/mes/año servidor: PASA','Foto con .. rechazada: PASA','RS titular en suplencia: PASA','Confirmación IA conserva origen y auditoría: PASA','Foto otra empresa rechazada: PASA','Emisión suplente copia RS de suplencia: PASA']) AS resultado;
ROLLBACK;